#!/bin/bash
# Full pipeline, safe to re-run at any time: finished results are skipped, so after a crash or a
# new session just launch it again:
#     cd /home/work/yunuikang/hyde && nohup bash run_all.sh >> logs/run_all.log 2>&1 &
# Progress:  python status.py        (do NOT edit this file while it runs)
#   CPU lane : E0 ML baselines
#   GPU lane : E1 tuning -> E2 final -> E3 ablation -> E4 unknown -> E5 dimension
set -u
cd "$(dirname "$0")"
mkdir -p logs
echo "[run_all] start $(date)"
python3 jobs.py cache >> logs/cache.log 2>&1
echo "[run_all] caches ready $(date)"
( python3 jobs.py E0 --threads 4 >> logs/E0.log 2>&1; echo "[run_all] E0 done $(date)" ) &
for stage in E1 E2 E3 E4 E5; do
    python3 jobs.py "$stage" --threads 2 >> "logs/$stage.log" 2>&1
    echo "[run_all] $stage done $(date)"
done
wait
echo "[run_all] all stages done $(date)"
